function renderLayers(){const focus=document.activeElement?.dataset?.select;$('layer-list').replaceChildren();for(const l of [...state.layers].reverse()){const row=document.createElement('div');row.className='layer-row'+(selection.has(l.id)?' selected':'')+(!l.visible?' muted':'');const b=document.createElement('button');b.className='layer-select';b.dataset.select=l.id;b.setAttribute('aria-pressed',String(selection.has(l.id)));b.innerHTML=icon(({text:'text',image:'image',chart:'chart'})[l.type]||'shapes');const label=document.createElement('span'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=l.name||'Adsız katman';sub.textContent=l.group?'Grup · '+l.type:({text:'Yazı',motif:'Vektör',shape:'Şekil',image:'Görsel',chart:'Grafik',symbol:'Sembol',drawing:'Serbest çizim'})[l.type];label.append(title,sub);b.append(label);row.append(b);for(const action of ['visibility','locking']){const control=document.createElement('button');control.className='icon-button';control.dataset[action]=l.id;control.innerHTML=icon(action==='visibility'?(l.visible?'eye':'hidden'):(l.locked?'lock':'unlock'));control.setAttribute('aria-label',(action==='visibility'?(l.visible?'Gizle: ':'Göster: '):(l.locked?'Kilidi aç: ':'Kilitle: '))+l.name);row.append(control);}$('layer-list').append(row);}if(focus)$('layer-list').querySelector(`[data-select="${focus}"]`)?.focus({preventScroll:true});}
function renderPages(){const tray=$('page-list'),scroll=tray.scrollLeft;tray.replaceChildren();$('page-count').textContent=doc.pages.length+' / '+MAX_PAGES;doc.pages.forEach((p,i)=>{const b=document.createElement('button');b.className='page-card';b.dataset.page=p.id;b.setAttribute('aria-pressed',String(p.id===doc.activePage));b.setAttribute('aria-label',(i+1)+'. sayfa: '+p.design.name);const image=document.createElement('span');image.innerHTML=buildSVG({...p.design,size:512},{prefix:'page-'+i,assets:doc.assets});const label=document.createElement('small');label.textContent=String(i+1).padStart(2,'0')+' / '+p.design.name;b.append(image,label);tray.append(b);});tray.scrollLeft=scroll;}
function renderCollection(){$('saved-grid').replaceChildren();$('saved-count').textContent=collection.length;$('empty-collection').hidden=collection.length>0;for(const item of collection){const wrapper=document.createElement('div');wrapper.className='saved-card';wrapper.append(makeCard(activeDesign(item.document),{id:item.id,label:item.document.name,category:item.document.pages.length+' SAYFA',saved:true,assets:item.document.assets}));const remove=document.createElement('button');remove.className='saved-delete';remove.dataset.remove=item.id;remove.innerHTML=icon('close');remove.setAttribute('aria-label',item.document.name+' kaydını sil');wrapper.append(remove);$('saved-grid').append(wrapper);}}
async function persistCollection(next){try{await writeLocal('collection',JSON.stringify(next));collection=next;renderCollection();return true;}catch{notify('Koleksiyon kaydedilemedi. FORMA dosyası olarak indirebilirsin.');return false;}}
let saving=false;
async function save(){if(saving)return;saving=true;try{const existing=collection.find(i=>i.id===activeSavedID);if(collection.some(i=>JSON.stringify(i.document)===JSON.stringify(doc))){notify('Bu belgenin son hali zaten projelerinde.');return;}if(!existing&&collection.length>=12){notify('Koleksiyonunda 12 belge var. Bir kaydı kaldır veya proje dosyası indir.');return;}const item={id:existing?.id||uid('saved'),document:normalizeDocument(doc),updatedAt:new Date().toISOString()};if(await persistCollection([item,...collection.filter(i=>i.id!==item.id)])){activeSavedID=item.id;scheduleDraft();notify(existing?'Projenin son hali güncellendi.':'Tüm sayfalarıyla projelerine kaydedildi.');}}finally{saving=false;}}
function addLayer(type,props={}){if(state.layers.length>=MAX_LAYERS){notify('Bir sayfada en fazla 40 katman olabilir.');return;}const id=uid('layer'),defaults=type==='text'?{name:'Yeni yazı',text:'Yeni fikir.',font:'sans',fontSize:48,weight:600,tracking:-1,leading:110,align:'middle'}:type==='motif'?{name:'Yeni motif',motif:'orbit'}:type==='image'?{name:'Görsel',width:240,height:220,fit:'cover',mask:'rect'}:type==='chart'?{name:'Veri grafiği',width:300,height:220,chart:'bar'}:type==='symbol'?{name:'Sembol',width:100,height:100,symbol:'sparkle'}:{name:'Yeni şekil',shape:'ellipse',width:100,height:100,corner:0};const l={id,type,x:50,y:50,visible:true,locked:false,opacity:100,rotation:0,scale:100,fill:type==='text'?'ink':'accent',...defaults,...props};selection=new Set([id]);selected=id;setInspector('element');mobilePanel('inspector');apply({layers:[...state.layers,l]});}
function addTextPreset(kind){const p={heading:{text:'Büyük bir fikir.',font:'display',fontSize:64,weight:800},subtitle:{text:'Her şey bir fikirle başlar.',fontSize:30,weight:600},body:{text:'Anlatmak istediğin hikâyeye\nburada yer aç. Kendi sözcüklerinle\ntasarımına anlam kat.',fontSize:18,weight:400,tracking:0,leading:145},quote:{text:'“Bir fikir\nher şeyi değiştirir.”',font:'serif',fontSize:39,italic:true,weight:400}}[kind];if(p)addLayer('text',p);}
function removeSelected(){if(!selection.size||!unlocked())return;const remove=new Set(selection);clearSelection();apply({layers:state.layers.filter(l=>!remove.has(l.id))});}
function copySelected(cut=false){if(!selection.size)return;const layers=chosen(),assets=doc.assets.filter(a=>layers.some(l=>l.type==='image'&&l.asset===a.id));clipboard={layers:structuredClone(layers),assets};if(cut)removeSelected();else notify(selection.size+' öğe kopyalandı.');render({fast:true});}
function pasteSelected(){if(!clipboard)return;if(state.layers.length+clipboard.layers.length>MAX_LAYERS){notify('40 katman sınırını aşan seçim yapıştırılamaz.');return;}let merged;try{merged=mergeAssetLibrary(doc.assets,clipboard.assets);}catch(error){notify(error.message);return;}const groups=new Map(),layers=clipboard.layers.map(l=>{if(l.group&&!groups.has(l.group))groups.set(l.group,uid('group'));return {...l,id:uid('layer'),name:(l.name+' kopya').slice(0,32),x:l.x+3,y:l.y+3,locked:false,group:l.group?groups.get(l.group):'',...(l.type==='image'?{asset:merged.ids.get(l.asset)||l.asset}:{})};});doc={...doc,assets:merged.assets};selection=new Set(layers.map(l=>l.id));selected=layers.at(-1).id;apply({layers:[...state.layers,...layers]});renderAssets();setInspector('element');}
function duplicateSelected(){if(!selection.size||!unlocked())return;const old=clipboard;clipboard={layers:structuredClone(chosen()),assets:[]};pasteSelected();clipboard=old;render({fast:true});}
function groupSelected(remove=false){if(!selection.size||!unlocked()||!remove&&selection.size<2)return;const group=remove?'':uid('group');apply({layers:state.layers.map(l=>selection.has(l.id)?{...l,group}:l)});}
function reorder(delta,edge=false){if(!selection.size||!unlocked())return;const layers=[...state.layers];if(edge){const selectedLayers=layers.filter(l=>selection.has(l.id)),rest=layers.filter(l=>!selection.has(l.id));apply({layers:delta>0?[...rest,...selectedLayers]:[...selectedLayers,...rest]});return;}if(delta>0){for(let i=layers.length-2;i>=0;i--)if(selection.has(layers[i].id)&&!selection.has(layers[i+1].id))[layers[i],layers[i+1]]=[layers[i+1],layers[i]];}else for(let i=1;i<layers.length;i++)if(selection.has(layers[i].id)&&!selection.has(layers[i-1].id))[layers[i],layers[i-1]]=[layers[i-1],layers[i]];apply({layers});}
function align(mode){if(selection.size<2||!unlocked())return;if(mode.startsWith('distribute')&&selection.size<3){notify('Dağıtım için en az üç öğe seç.');return;}apply(alignLayers(state,[...selection],mode,bounds));}
async function uploadFiles(files){for(const file of [...files].slice(0,MAX_ASSETS)){try{if(doc.assets.length>=MAX_ASSETS)throw Error('En fazla 24 görsel ekleyebilirsin.');const asset=await importImage(file),existing=doc.assets.find(a=>a.data===asset.data);if(!existing&&doc.assets.reduce((n,a)=>n+a.data.length,0)+asset.data.length>MAX_ASSET_TOTAL)throw Error('Bu belgenin görsel alanı doldu. Kullanmadığın görselleri kaldır.');if(!existing)doc={...doc,assets:[...doc.assets,asset]};addLayer('image',{asset:(existing||asset).id,name:asset.name,width:240,height:Math.min(340,Math.max(70,240*asset.height/asset.width))});renderAssets();}catch(error){notify(error.message||'Görsel eklenemedi.');}}}
function renderAssets(){$('asset-grid').replaceChildren();$('asset-empty').hidden=doc.assets.length>0;for(const a of doc.assets){const wrap=document.createElement('div');wrap.className='asset-card';const b=document.createElement('button');b.dataset.asset=a.id;b.setAttribute('aria-label',a.name+' görselini ekle');const image=document.createElement('img');image.src=a.data;image.alt=a.name;const label=document.createElement('span');label.textContent=a.name;b.append(image,label);const remove=document.createElement('button');remove.className='saved-delete';remove.dataset.removeAsset=a.id;remove.innerHTML=icon('close');const used=doc.pages.some(p=>p.design.layers.some(l=>l.type==='image'&&l.asset===a.id));remove.disabled=used;remove.title=used?'Bu görsel sayfalarda kullanılıyor':'Görseli kaldır';remove.setAttribute('aria-label',a.name+' görselini kaldır');wrap.append(b,remove);$('asset-grid').append(wrap);}}
