  if(b.dataset.command){commands[b.dataset.command]?.();$('file-menu').hidden=true;$('file-menu-button').setAttribute('aria-expanded','false');$('canvas-context').hidden=true;return;}
  if(b.dataset.page){pageByID(b.dataset.page);return;}if(b.dataset.template){openTemplate(b.dataset.template,b);return;}if(b.dataset.category){category=b.dataset.category;filterTemplates();return;}
  if(b.dataset.palette){const p=PALETTES.find(p=>p.id===b.dataset.palette);if(p)apply({background:p.background,primary:p.primary,accent:p.accent});return;}if(b.dataset.format){apply({format:b.dataset.format});return;}
