  if(b.dataset.add){addLayer(b.dataset.add);return;}if(b.dataset.shape){addLayer('shape',{shape:b.dataset.shape,height:b.dataset.shape==='line'?3:100});return;}if(b.dataset.symbol){addLayer('symbol',{symbol:b.dataset.symbol,name:SYMBOLS[b.dataset.symbol].name});return;}if(b.dataset.chart){addLayer('chart',{chart:b.dataset.chart});return;}if(b.dataset.textPreset){addTextPreset(b.dataset.textPreset);return;}
  if(b.dataset.align){patchLayer({align:b.dataset.align});return;}if(b.dataset.asset){const a=doc.assets.find(a=>a.id===b.dataset.asset);if(a)addLayer('image',{asset:a.id,name:a.name});return;}if(b.dataset.removeAsset){if(doc.pages.some(p=>p.design.layers.some(l=>l.asset===b.dataset.removeAsset)))return;changeDocument({...doc,assets:doc.assets.filter(a=>a.id!==b.dataset.removeAsset)});renderAssets();return;}
  if(b.dataset.remove){persistCollection(collection.filter(i=>i.id!==b.dataset.remove));return;}if(b.dataset.saved){const item=collection.find(i=>i.id===b.dataset.saved);if(item){activeSavedID=item.id;clearSelection();changeDocument(item.document);renderAssets();setInspector('canvas');}return;}if(b.dataset.close)$(b.dataset.close)?.close();
