$('artwork').addEventListener('contextmenu',e=>{e.preventDefault();const target=e.target.closest('[data-layer]');if(target&&!selection.has(target.dataset.layer))pick(target.dataset.layer);const menu=$('canvas-context');menu.hidden=false;menu.style.left=Math.max(8,Math.min(innerWidth-210,e.clientX))+'px';menu.style.top=Math.max(8,Math.min(innerHeight-330,e.clientY))+'px';menu.querySelector('button').focus();});
