document.addEventListener('keydown',e=>{
  if($('presentation-dialog').open){if(['ArrowLeft','ArrowRight',' '].includes(e.key)){e.preventDefault();presentationIndex=Math.max(0,Math.min(doc.pages.length-1,presentationIndex+(e.key==='ArrowLeft'?-1:1)));renderPresentation();}return;}
  const command=e.ctrlKey||e.metaKey,key=e.key.toLowerCase(),editing=!!e.target.closest('input,textarea,select,[contenteditable=true]');
  if(command&&key==='s'&&!document.querySelector('dialog[open]')){e.preventDefault();saveProject();return;}if(editing||document.querySelector('dialog[open]'))return;
  if(e.code==='Space'&&e.target===$('artwork')){e.preventDefault();spaceHeld=true;stage.classList.add('can-pan');return;}if(e.key==='Escape'){$('canvas-context').hidden=true;$('file-menu').hidden=true;chooseIDs([]);return;}if(command&&key==='z'){e.preventDefault();moveHistory(e.shiftKey?'redo':'undo');return;}
  if(command&&key==='d'&&selection.size){e.preventDefault();duplicateSelected();return;}if(command&&key==='g'){e.preventDefault();groupSelected(e.shiftKey);return;}if(command&&key==='c'&&selection.size){e.preventDefault();copySelected();return;}if(command&&key==='x'&&selection.size&&unlocked()){e.preventDefault();copySelected(true);return;}if(command&&key==='v'&&clipboard){e.preventDefault();pasteSelected();return;}
  if(e.target!==$('artwork'))return;if(e.key==='F2'&&selection.size===1){e.preventDefault();$('layer-name').focus();$('layer-name').select();return;}if(['Delete','Backspace'].includes(e.key)){e.preventDefault();removeSelected();return;}
  if(!selection.size||!unlocked())return;const f=canvasSize(state),step=e.shiftKey?10:1,delta={ArrowLeft:[-step/f.width*100,0],ArrowRight:[step/f.width*100,0],ArrowUp:[0,-step/f.height*100],ArrowDown:[0,step/f.height*100]}[e.key];if(delta){e.preventDefault();apply({layers:state.layers.map(l=>selection.has(l.id)?{...l,x:l.x+delta[0],y:l.y+delta[1]}:l)});}
});
