addEventListener('hashchange',()=>{if(!location.hash)return;try{activeSavedID=null;clearSelection();changeDocument(decodeDocument(location.hash.slice(1)));renderAssets();notify('Paylaşılan belge açıldı.');}catch{notify('Bu tasarım bağlantısı geçerli değil.');}});
$('open-project').addEventListener('click',()=>$('project-file').click());$('project-file').addEventListener('change',async e=>{const file=e.target.files[0];try{if(!file)return;if(file.size>MAX_PROJECT_BYTES)throw Error('Proje dosyası en fazla 20 MB olabilir.');const next=parseDocument(await file.text());await validateAssets(next.assets);activeSavedID=null;clearSelection();changeDocument(next);renderAssets();setInspector('canvas');notify('Proje, tüm sayfa ve görselleriyle açıldı.');}catch(error){notify(error.message||'Proje açılamadı.');}finally{e.target.value='';}});
function renderExport(){const f=dimensions(state),format=$('format').value,json=format==='json',all=$('export-scope').value==='all',count=json||all?doc.pages.length:1;$('export-preview').innerHTML=buildSVG(state,{prefix:'export',assets:doc.assets});$('size').disabled=json||format==='pdf';$('export-scope').disabled=json;$('export-dimensions').textContent=json?doc.pages.length+' sayfa · '+doc.assets.length+' görsel · .forma.json':format==='pdf'?count+' sayfa · Raster PDF belgesi':f.exportWidth+' × '+f.exportHeight+' px · '+count+' sayfa'+(count>1?' · ZIP arşivi':'');$('font-note').textContent=json?'Tüm sayfalar ve görseller dosyada saklanır. “Proje aç” ile devam edebilirsin.':format==='pdf'?'PDF sayfaları 2048 px uzun kenarda rasterleştirilir; yazılar vektör olarak düzenlenemez.':format==='jpg'?'JPG saydamlığı desteklemez; boş alanlar beyaz zeminle birleştirilir.':'SVG sistem fontlarını kullanır. PNG/JPG/WebP görünümü sabitler. Birden fazla sayfa ZIP içinde indirilir.';}
