document.querySelectorAll('dialog:not(#presentation-dialog)').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}));
$('download-button').addEventListener('click',async()=>{if(exporting)return;exporting=true;const snapshot=normalizeDocument(doc),format=$('format').value,exportSize=Number($('size').value),pages=$('export-scope').value==='all'?snapshot.pages:snapshot.pages.filter(p=>p.id===snapshot.activePage);$('download-button').disabled=true;$('download-label').textContent='Hazırlanıyor…';try{let blob,extension=format;if(format==='json'){blob=new Blob([documentJSON(snapshot)],{type:'application/json'});extension='forma.json';}else if(format==='pdf')blob=await documentPDF(pages,snapshot.assets);else{const files=[];for(const [i,p]of pages.entries()){const design={...p.design,size:exportSize},data=format==='svg'?buildSVG(design,{assets:snapshot.assets}):await rasterBlob(design,snapshot.assets,format);files.push({name:'sayfa-'+String(i+1).padStart(2,'0')+'.'+format,data});}if(files.length>1){blob=await zipFiles(files);extension='zip';}else blob=typeof files[0].data==='string'?new Blob([files[0].data],{type:'image/svg+xml;charset=utf-8'}):files[0].data;}fileDownload(blob,extension,snapshot.name);notify('Dosyan hazır. '+(format==='json'?'Düzenlemeye daha sonra devam edebilirsin.':pages.length+' sayfa dışa aktarıldı.'));}catch(error){notify(error.message||'Dosya oluşturulamadı. Daha küçük bir boyut deneyebilirsin.');}finally{exporting=false;$('download-button').disabled=false;$('download-label').textContent='Dosyayı indir';}});
function renderPresentation(){const page=doc.pages[presentationIndex];$('presentation-art').innerHTML=buildSVG(page.design,{prefix:'present',assets:doc.assets});$('presentation-count').textContent=(presentationIndex+1)+' / '+doc.pages.length;$('presentation-prev').disabled=presentationIndex===0;$('presentation-next').disabled=presentationIndex===doc.pages.length-1;}
$('present-button').addEventListener('click',()=>{presentationIndex=doc.pages.findIndex(p=>p.id===doc.activePage);$('presentation-dialog').showModal();renderPresentation();});$('presentation-prev').addEventListener('click',()=>{presentationIndex=Math.max(0,presentationIndex-1);renderPresentation();});$('presentation-next').addEventListener('click',()=>{presentationIndex=Math.min(doc.pages.length-1,presentationIndex+1);renderPresentation();});

