async function openTemplate(id,button,patch={}){const request=++templateRequest;button?.setAttribute('aria-busy','true');try{const design=normalizeDesign({...templateDesign(id),...patch}),assets=await pageAssets(design,doc.assets);if(request!==templateRequest)return false;doc={...doc,assets};replaceDesign(design);renderAssets();return true;}catch(error){if(request===templateRequest)notify(error.message||'Şablon yüklenemedi.');return false;}finally{button?.removeAttribute('aria-busy');}}
const CAMPAIGN_FIELDS=[['brand','İşletme adı',1,60],['eyebrow','Üst başlık',1,80],['title','Ana başlık',4,160],['price','Fiyat / teklif',1,70],['details','Özellikler / hizmetler',6,320],['cta','Çağrı metni',1,60],['contact','Telefon / iletişim',1,60],['website','Web adresi',1,80],['address','Konum',1,80],['period','Kampanya dönemi',1,60],['terms','Koşullar / kısa not',2,150]];
let campaignFormKey='';
function businessTemplate(){const t=TEMPLATES.find(t=>t.id===state.template);return t?.commercial&&state.layers.some(l=>l.id==='hero')?t:null;}
function renderCampaign(){
 const t=businessTemplate();$('campaign-tab').hidden=!t;if(!t){if(!$('campaign-panel').hidden)setInspector('canvas');return;}
 const fields=CAMPAIGN_FIELDS.filter(([id])=>state.layers.some(l=>l.id===id&&l.type==='text')),key=t.id+'|'+fields.map(f=>f[0]).join(',');
 $('campaign-sector-name').textContent=CATEGORIES.find(c=>c.id===t.category).name+' / '+t.name;
 if(campaignFormKey!==key){campaignFormKey=key;$('campaign-fields').replaceChildren();for(const [id,name,lines,limit]of fields){const label=document.createElement('label'),input=document.createElement(lines>1?'textarea':'input');label.htmlFor='campaign-'+id;label.textContent=({meeting:{price:'Tarih / katılım',details:'Gündem / program',period:'Etkinlik serisi'},hotel:{price:'Fiyat / konaklama',details:'Oda / dahil olanlar'},tourism:{price:'Tur fiyatı / teklif',details:'Rota / program'},pilates:{price:'Ders / üyelik paketi',details:'Ders planı / kapsam'}}[t.category]?.[id]||name);input.id='campaign-'+id;input.maxLength=limit*2;input.autocomplete='off';input.spellcheck=false;if(lines>1)input.rows=lines;else input.type=id==='contact'?'tel':'text';const update=record=>{const text=cleanText(input.value,limit,'',lines);apply({layers:state.layers.map(l=>l.id===id?{...l,text}:l)},{commit:record});if(record)input.value=text;};input.addEventListener('input',()=>update(false));input.addEventListener('change',()=>update(true));$('campaign-fields').append(label,input);}
   $('campaign-photos').replaceChildren();const sector=t.sector||t.category;for(const photo of PHOTO_CATALOG.filter(p=>p.sector===sector)){const b=document.createElement('button');b.className='campaign-photo';b.dataset.stockPhoto=photo.asset;b.title=photo.name;b.setAttribute('aria-label',photo.name+' fotoğrafını kullan');const img=document.createElement('img');img.src=photo.path;img.alt=photo.name;const label=document.createElement('span');label.textContent=photo.name;b.append(img,label);b.addEventListener('click',async()=>{b.setAttribute('aria-busy','true');try{await replaceHero(await stockPhoto(photo.asset));}catch(error){notify(error.message);}finally{b.removeAttribute('aria-busy');}});$('campaign-photos').append(b);}}
 for(const [id]of fields)setValue('campaign-'+id,state.layers.find(l=>l.id===id)?.text||'');const hero=state.layers.find(l=>l.id==='hero');document.querySelectorAll('[data-stock-photo]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.stockPhoto===hero?.asset)));
}
async function replaceHero(asset){const merged=mergeAssetLibrary(doc.assets,[asset]);doc={...doc,assets:merged.assets};apply({layers:state.layers.map(l=>l.id==='hero'&&l.type==='image'?{...l,asset:merged.ids.get(asset.id)||asset.id,cropX:0,cropY:0,cropZoom:100}:l)});renderAssets();}
